export interface MouzaItem {
  name: string;
  jlNo: string;
}

export interface UnionItem {
  name: string;
  mouzas: MouzaItem[];
}

export interface UpazilaItem {
  name: string;
  unions: UnionItem[];
}

export interface DistrictItem {
  name: string;
  bnName: string;
  upazilas: UpazilaItem[];
}

export interface DivisionItem {
  name: string;
  bnName: string;
  districts: DistrictItem[];
}

